    sorted((ROOT/"skills").glob("*/passes/*.md"))

def slugify(text):
    # strip markdown formatting like backticks, bold, links
    text = re.sub(r'`([^`]*)`', r'\1', text)
    text = re.sub(r'\*\*([^*]*)\*\*', r'\1', text)
    text = re.sub(r'\*([^*]*)\*', r'\1', text)
    text = re.sub(r'\[([^\]]*)\]\([^)]*\)', r'\1', text)
    slug = text.lower()
    slug = re.sub(r'[^\w\s-]', '', slug)
    slug = re.sub(r'\s+', '-', slug.strip())
    return slug

def extract_headings(path):
    headings = []
    in_fence = False
    for line in path.read_text().splitlines():
        if line.strip().startswith("```"):
            in_fence = not in_fence
            continue
        if in_fence:
            continue
        m = re.match(r'^(#{1,6})\s+(.*)$', line)
        if m:
            headings.append(m.group(2).strip())
    return headings

def anchors_for(path):
    headings = extract_headings(path)
    seen = {}
    anchors = set()
    for h in headings:
        slug = slugify(h)
        if slug in seen:
            seen[slug] += 1
            anchors.add(f"{slug}-{seen[slug]}")
        else:
            seen[slug] = 0
            anchors.add(slug)
    return anchors

anchor_cache = {}
def get_anchors(p):
    if p not in anchor_cache:
        anchor_cache[p] = anchors_for(p) if p.exists() else None
    return anchor_cache[p]

link_re = re.compile(r'\[([^\]]*)\]\(([^)]+)\)')

for doc in DOC_FILES:
