            if "#" not in target and target == "":
                continue
            if "#" in target:
                filepart, anchor = target.split("#", 1)
            else:
                filepart, anchor = target, None
            if filepart == "":
                target_path = doc
            else:
                target_path = (doc.parent / filepart).resolve()
            if not target_path.exists():
                print(f"BROKEN FILE: {doc.relative_to(ROOT)}:{lineno} -> {target}")
                continue
            if anchor:
                anchors = get_anchors(target_path)
                if anchors is not None and anchor not in anchors:
                    print(f"BROKEN ANCHOR: {doc.relative_to(ROOT)}:{lineno} -> {target}  (anchor '{anchor}' not found in {target_path.relative_to(ROOT)})")
